window.renderCatalog = function(lang, query, category) {
  lang = lang === 'en' ? 'en' : 'ru';
  const categories = {weapon:{ru:'Оружие',en:'Weapons'},armor:{ru:'Броня',en:'Armor'},gear:{ru:'Снаряжение',en:'Gear'},cyberware:{ru:'Киберимпланты',en:'Cyberware'},ammo:{ru:'Боеприпасы',en:'Ammunition'},attachment:{ru:'Модификации',en:'Attachments'},programs:{ru:'Программы и кибердеки',en:'Programs and cyberdecks'},fashion:{ru:'Мода',en:'Fashion'},services:{ru:'Услуги',en:'Services'},drugs:{ru:'Вещества',en:'Drugs'},housing:{ru:'Жильё и образ жизни',en:'Housing and lifestyle'},vehicles:{ru:'Транспорт',en:'Vehicles'},defenses:{ru:'Защита помещений',en:'Home defenses'}};
  const t = lang === 'ru' ? {page:'СТР.', add:'Добавить', buy:'Купить', loss:'Потеря Humanity', install:'Установка', empty:'Ничего не найдено. Попробуйте другой запрос.'} : {page:'PAGE', add:'Add', buy:'Buy', loss:'Humanity loss', install:'Installation', empty:'No items found. Try another search.'};
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const q = String(query || '').trim().toLocaleLowerCase();
  const list = window.CATALOG.filter(item => (!category || category === 'all' || item.category === category) && (!q || [item.name.ru,item.name.en,item.details.ru,item.details.en,item.priceNote?.ru,item.priceNote?.en,item.priceUnit?.ru,item.priceUnit?.en,String(item.price),String(item.page)].some(v => String(v || '').toLocaleLowerCase().includes(q))));
  if (!list.length) return `<div class="empty compact"><p>${e(t.empty)}</p></div>`;
  return list.map(item => {
    let cyber = item.stats.humanityLoss != null ? `<div class="catalog-meta">${e(t.loss)}: ${e(item.stats.humanityLoss)} · ${e(t.install)}: ${e(item.stats.installation)}</div>` : '';
    return `<article class="catalog-card card"><div class="rule-top"><span class="badge">${e(categories[item.category]?.[lang] || item.category)}</span><span>${e(t.page)} ${e(item.page)}</span></div><h3>${e(item.name[lang])}</h3>${item.details[lang] ? `<p>${e(item.details[lang])}</p>` : ''}${cyber}<div class="catalog-foot"><strong>${item.price==null?e(item.priceNote?.[lang]||(lang==='ru'?'Цена не указана':'Price not specified')):e(item.price)+' eb'}${item.priceUnit?.[lang]?' / '+e(item.priceUnit[lang]):''}</strong><span class="catalog-actions"><button type="button" class="btn ghost catalog-add" data-action="catalog-add" data-id="${e(item.id)}">+ ${e(t.add)}</button><button type="button" class="btn ghost catalog-buy" data-action="catalog-buy" data-id="${e(item.id)}">${e(t.buy)}</button></span></div></article>`;
  }).join('');
};
